def is_good(m):
    """Checks if a positive integer m (with distinct nonzero digits) is 'good'."""
    if m <= 0:
        return False
    m_str = str(m)

    # Condition 1: Single-digit numbers are good
    if len(m_str) == 1:
        return True

    # Condition 2: Check removals
    for i in range(len(m_str)):
        # Form the number d' by removing the digit at index i
        d_prime_str = m_str[:i] + m_str[i+1:]
        if not d_prime_str:
            continue

        d_prime = int(d_prime_str)

        # Check if d' is a divisor of m
        if m % d_prime == 0:
            # Check if d' is also a good number (recursive check)
            if is_good(d_prime):
                return True

    return False

